{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "These signs include safety, health, or behavioral concerns such as bullying, threats, substance abuse, mental health issues, self-harm, or suicidal thoughts.",
      "rationale": "Conveys the general definition and several examples, but omits harassment, intimidation, cyberbullying, and the express coverage of victims and students receiving threats."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Beginning July 1, 2026, this bill would require each local education agency (LEA) and public charter school to use a computer-based system for teachers and school staff to record students’ “early warning signs.”",
      "rationale": "Conveys the covered entities, required computer-based system, and teacher and staff recording duties. The existing-system exemption is explained later."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Schools must train teachers and staff to recognize these signs and use the system.",
      "rationale": "Conveys both required training subjects for teachers and staff, with the exemption addressed later."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "The system must align with the specified bullying, discipline, and school safety policies",
      "rationale": "Conveys alignment in the three subject areas, but does not distinguish the required School Discipline Act compliance from policies or identify the required school safety plans."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The system must align with the specified bullying, discipline, and school safety policies; keep the entered information;",
      "rationale": "Together with the described data-entry system, retaining entered information conveys the database's required receiving and maintenance functions."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "and immediately notify the LEA threat assessment team or a designated charter-school employee when a sign is recorded.",
      "rationale": "Conveys the triggering entry, immediate notification, and both alternative recipients."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The recipient must review the notice and any earlier notices for that student and decide whether further action is needed.",
      "rationale": "Conveys review of current and previous notifications and the required decision about further action. The exemption is addressed later."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "Each LEA and public charter school would have to report annually to the Department of Education on information from the preceding school year. Reports must include the number of signs recorded",
      "rationale": "Includes the reporting entities, recipient, annual frequency, preceding-school-year period, and total sign count."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "with counts broken down by who entered them and relevant job or teaching details",
      "rationale": "Conveys disaggregation generally, but omits the specific teacher grade-level and subject-area breakdowns and staff position, assignment, and duties breakdowns."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "counts of students with multiple signs and the number of signs for each such student",
      "rationale": "Conveys both the number of students with multiple entries and the number of entries for each such student."
    },
    {
      "proposition_id": "P11",
      "status": "partial",
      "summary_quote": "and general descriptions of the signs and responses. Reports must not identify students and must comply with the listed privacy laws.",
      "rationale": "Conveys general descriptions and nonidentification, but does not specify that responses must be described for each entered sign."
    },
    {
      "proposition_id": "P12",
      "status": "full",
      "summary_quote": "Reports must not identify students",
      "rationale": "Conveys the report-wide prohibition on information that identifies students."
    },
    {
      "proposition_id": "P13",
      "status": "partial",
      "summary_quote": "Reports must not identify students and must comply with the listed privacy laws.",
      "rationale": "Conveys a privacy-law compliance obligation, but never identifies FERPA, the state confidentiality provision, or the Data Accessibility, Transparency, and Accountability Act, and does not expressly cover all other relevant privacy laws."
    },
    {
      "proposition_id": "P14",
      "status": "full",
      "summary_quote": "The commissioner of education could withhold an amount of state funds the commissioner determines from an LEA or public charter school that does not comply, until it complies.",
      "rationale": "Conveys the commissioner's discretionary withholding authority, covered entities, noncompliance condition, discretion over the amount, and duration."
    },
    {
      "proposition_id": "P15",
      "status": "full",
      "summary_quote": "The system and training requirements, and the notification and review requirements, would not apply to a school system that had a system for documenting students’ early warning signs in place before July 1, 2026, as long as it continues to maintain and use that system.",
      "rationale": "Conveys the exempt requirements, pre-July 1, 2026 implementation condition, and continued maintenance and use. The separately stated universal reporting duty remains outside this exemption."
    },
    {
      "proposition_id": "P16",
      "status": "full",
      "summary_quote": "Beginning July 1, 2026, this bill would require",
      "rationale": "Conveys the act's effective date."
    }
  ]
}
